pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testRegression_property() public {
        RevertingRecipient recipient = new RevertingRecipient();
        vm.deal(address(c), 1 ether);
        bool ok;
        try c.withdrawAll(address(recipient)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertFalse(ok);
    }
}

